import { IHikingMenuSaveDTO } from '../@types/hiking.backendTypes';
import { IHikingMenuSave } from '../@types/hiking.baseTypes';

export const mapHikingMenuSaveToFront = (backData: IHikingMenuSaveDTO): IHikingMenuSave => {
  return {
    id: +backData.id,
    name: backData.name,
    date: new Date(backData.date),
    userName: backData.user,
    confirmUser: backData.confirm_user_name,
    confirmDate: backData.confirm_date ? new Date(backData.confirm_date) : null,
    isCurrent: backData.is_current === '1',
  };
};
